import { expect, expectStatus, test } from "../../fixtures";

type DocumentBody = { id: string; status: "processing" | "extracted" | "failed" };
type ExtractionBody = { id: string; document_id: string; kind: string; status: string };

test.describe("LIF-07 vendor lifecycle", () => {
  test(
    "A certificate that expires today can still be approved",
    { tag: "@LIF-07" },
    async ({ apiAs }) => {
      // Arrange: a unique vendor so parallel tests don't collide on a shared database.
      const suffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
      const member = await apiAs("member");
      const reviewer = await apiAs("reviewer");

      const vendor = await expectStatus<{ id: string }>(
        await member.post("/api/vendors", {
          data: {
            name: `LIF-07 Expiry Vendor ${suffix}`,
            category: "services",
            contact_email: `lif07-expiry-${suffix}@example.test`,
          },
        }),
        201,
      );

      // The certificate's expiry date is carried in its content: today, 2026-11-11.
      const certificate = Buffer.from(
        "%PDF-1.4\nInsurance certificate\nPolicy expires: 2026-11-11\n",
      );
      const upload = await expectStatus<DocumentBody>(
        await member.post(`/api/vendors/${vendor.id}/documents`, {
          multipart: {
            kind: "insurance_certificate",
            file: {
              name: `certificate-${suffix}.pdf`,
              mimeType: "application/pdf",
              buffer: certificate,
            },
          },
        }),
        201,
      );

      // Wait for extraction to finish so the extraction can be reviewed.
      await expect
        .poll(
          async () => {
            const doc = await expectStatus<DocumentBody>(
              await member.get(`/api/documents/${upload.id}`),
              200,
            );
            return doc.status;
          },
          { timeout: 30_000, intervals: [250, 500, 1000] },
        )
        .not.toBe("processing");

      const extraction = await expectStatus<ExtractionBody>(
        await member.get(`/api/documents/${upload.id}/extraction`),
        200,
      );
      expect(extraction.kind).toBe("insurance_certificate");
      expect(extraction.status).toBe("pending_review");

      // Move the vendor into review.
      await expectStatus(await member.post(`/api/vendors/${vendor.id}/submit`), 200);

      // Act: a reviewer approves the insurance certificate extraction.
      const decision = await reviewer.post(`/api/extractions/${extraction.id}/decision`, {
        data: { decision: "approve" },
      });

      // Assert
      const body = await expectStatus<ExtractionBody>(decision, 200);
      expect(body.status).toBe("approved");
    },
  );
});
